//! Integration tests for all shorthand helper methods generated by impl_helpers!.
//! Each test shows one shorthand in minimal working usage.

use reqwest::blocking::Client;
use whyhttp::Whyhttp;

fn client() -> Client {
    Client::new()
}

// ── when_* on Whyhttp ─────────────────────────────────────────────────────────

#[test]
fn when_path() {
    let server = Whyhttp::run();
    server.when_path("/greet").response().status(200u16);
    client()
        .get(format!("{}/greet", server.url()))
        .send()
        .unwrap();
}

#[test]
fn when_method() {
    let server = Whyhttp::run();
    server.when_method("DELETE").response().status(204u16);
    let resp = client().delete(server.url()).send().unwrap();
    assert_eq!(resp.status().as_u16(), 204);
}

#[test]
fn when_query() {
    let server = Whyhttp::run();
    server.when_query("sort", "asc").response().status(200u16);
    client()
        .get(format!("{}/?sort=asc", server.url()))
        .send()
        .unwrap();
}

