// ── response_* on Whyhttp ─────────────────────────────────────────────────────

#[test]
fn response_status() {
    let server = Whyhttp::run();
    server.response_status(418u16);
    let resp = client().get(server.url()).send().unwrap();
    assert_eq!(resp.status().as_u16(), 418);
}

#[test]
fn response_header() {
    let server = Whyhttp::run();
    server.response_header("x-custom", "yes");
    let resp = client().get(server.url()).send().unwrap();
    assert_eq!(
        resp.headers().get("x-custom").and_then(|v| v.to_str().ok()),
        Some("yes")
    );
}

#[test]
fn response_body() {
    let server = Whyhttp::run();
    server.response_body("pong");
    let resp = client().get(server.url()).send().unwrap();
    assert_eq!(resp.text().unwrap(), "pong");
}

// ── when_* / should_* / response_* on builder types ─────────────────────────

#[test]
fn when_path_from_response_builder() {
    // when_path is also available on WhyhttpResponse (starts a new expectation)
    let server = Whyhttp::run();
    server
        .when_path("/first")
        .response()
        .status(200u16)
        .when_path("/second")
        .response()
        .status(201u16);

    let r1 = client()
        .get(format!("{}/first", server.url()))
        .send()
        .unwrap();
    assert_eq!(r1.status().as_u16(), 200);

    let r2 = client()
        .get(format!("{}/second", server.url()))
        .send()
        .unwrap();
    assert_eq!(r2.status().as_u16(), 201);
}

#[test]
fn should_method_from_when_builder() {
    // should_method is available on WhenWhyhttpRequest
    let server = Whyhttp::run();
    server
        .when()
        .path("/post-only")
        .should_method("POST")
        .response()
        .status(200u16);

    client()
        .post(format!("{}/post-only", server.url()))
        .send()
        .unwrap();
}

#[test]
fn response_status_from_when_builder() {
    // response_status is available on WhenWhyhttpRequest
    let server = Whyhttp::run();
    server.when().path("/created").response_status(201u16);

    let resp = client()
        .get(format!("{}/created", server.url()))
        .send()
        .unwrap();
    assert_eq!(resp.status().as_u16(), 201);
}

#[test]
fn response_body_from_should_builder() {
    // response_body is available on ShouldWhyhttpRequest
    let server = Whyhttp::run();
    server.when().path("/msg").should().response_body("ok");

    let resp = client()
        .get(format!("{}/msg", server.url()))
        .send()
        .unwrap();
    assert_eq!(resp.text().unwrap(), "ok");
}

#[test]
fn when_path_from_should_builder() {
    // when_path available on ShouldWhyhttpRequest — starts a new expectation
    let server = Whyhttp::run();
    server
        .when_path("/a")
        .should()
        .when_path("/b") // ← called on ShouldWhyhttpRequest
        .response()
        .status(201u16);

    client().get(format!("{}/a", server.url())).send().unwrap();
    client().get(format!("{}/b", server.url())).send().unwrap();
}
